import{_ as r,o as t,c as a,a3 as n}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Center dashboard overview","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/overview.md","filePath":"user/center/overview.md"}'),s={name:"user/center/overview.md"};function o(i,e,d,c,h,l){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="center-dashboard-overview" tabindex="-1">Center dashboard overview <a class="header-anchor" href="#center-dashboard-overview" aria-label="Permalink to &quot;Center dashboard overview&quot;">​</a></h1><p>The dashboard is where a center runs its business: services, reservations, purchases, promotions, team and payouts.</p><h2 id="getting-in" tabindex="-1">Getting in <a class="header-anchor" href="#getting-in" aria-label="Permalink to &quot;Getting in&quot;">​</a></h2><ol><li>Sign in with your phone number and the one-time code.</li><li>Pick your center. The <strong>owner</strong> (primary user) is asked for their password again before entering.</li></ol><p>You can only use the dashboard when the platform has set your center to <strong>Active</strong>. A <strong>Pending</strong> center is waiting for review; a <strong>Blocked</strong> center cannot operate.</p><h2 id="what-you-see-depends-on-your-permissions" tabindex="-1">What you see depends on your permissions <a class="header-anchor" href="#what-you-see-depends-on-your-permissions" aria-label="Permalink to &quot;What you see depends on your permissions&quot;">​</a></h2><p>The owner can do everything. Other team members only see what their permissions allow, for example managing one service type, viewing purchases, or handling reservations. See <a href="./team">Team and permissions</a>.</p><h2 id="going-live" tabindex="-1">Going live <a class="header-anchor" href="#going-live" aria-label="Permalink to &quot;Going live&quot;">​</a></h2><p><strong>Profile completion</strong> lists what is missing (for example description, images or services). Set your center <strong>Visible</strong> when you want clients to find it.</p><h2 id="privacy-policy-and-terms" tabindex="-1">Privacy policy and terms <a class="header-anchor" href="#privacy-policy-and-terms" aria-label="Permalink to &quot;Privacy policy and terms&quot;">​</a></h2><p>The center app links to the privacy policy and terms and conditions for centers. They open inside the app in your language.</p><h2 id="main-areas" tabindex="-1">Main areas <a class="header-anchor" href="#main-areas" aria-label="Permalink to &quot;Main areas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Page</th></tr></thead><tbody><tr><td>Services, trainers and prices</td><td><a href="./services">Managing services</a></td></tr><tr><td>Opening hours, closures and blocks</td><td><a href="./schedules-blocks">Schedules, periods and blocks</a></td></tr><tr><td>Bookings</td><td><a href="./reservations">Reservations</a></td></tr><tr><td>Money</td><td><a href="./purchases-payouts">Purchases, balance and payouts</a></td></tr><tr><td>Discounts</td><td><a href="./promotions">Promotions</a></td></tr><tr><td>Staff</td><td><a href="./team">Team and permissions</a></td></tr></tbody></table><p><strong>Plans and subscription:</strong> browse the plans, subscribe, and see your current subscription. Only the owner can cancel. Subscriptions last one billing period and have no VAT or invoices.</p><p>Also: <strong>Analytics</strong> (your sales and bookings), <strong>Ratings</strong>, <strong>Blocked clients</strong>, <strong>Clients</strong> and <strong>Notifications</strong>. You can export purchases and clients if you have the export permission.</p>',15)])])}const g=r(s,[["render",o]]);export{u as __pageData,g as default};
